// ===== shared helpers (prepended to every Code node by make_pipeline.py) =====
// Nothing to configure in this block - settings live at the top of the node that uses them
// (time zone: Extract IOCs + Filter; links, clients, thresholds, model: Risk + MITRE Engine).

const LEVEL_STYLE = {
  critical: { label: 'CRITICAL',     color: '#dc2626', bg: '#fef2f2', border: '#fecaca', emoji: ':red_circle:' },
  high:     { label: 'HIGH',         color: '#ea580c', bg: '#fff7ed', border: '#fed7aa', emoji: ':large_orange_circle:' },
  medium:   { label: 'MEDIUM',       color: '#d97706', bg: '#fffbeb', border: '#fde68a', emoji: ':large_yellow_circle:' },
  low:      { label: 'LOW',          color: '#16a34a', bg: '#f0fdf4', border: '#bbf7d0', emoji: ':large_green_circle:' }
};

// Invisible / bidirectional-override characters can disguise text in an alert (U+202E reverses what follows);
// control characters would break subjects and table rows. Both are stripped from everything read from the logs.
const INVISIBLE_RE = /[\u200b-\u200f\u202a-\u202e\u2066-\u2069\ufeff]/g;
const CONTROL_RE = /[\u0000-\u001f\u007f]+/g;

function val(s) {
  if (s === undefined || s === null) return '';
  s = String(s).replace(INVISIBLE_RE, '').replace(CONTROL_RE, ' ').trim();
  const l = s.toLowerCase();
  if (s === '' || s === '-' || l === 'null' || l === '(null)' || l === 'n/a' || l === 'none' || l === 'undefined') return '';
  return s;
}

function clip(s, n) {
  s = String(s == null ? '' : s).replace(INVISIBLE_RE, '').replace(CONTROL_RE, ' ').replace(/\s+/g, ' ').trim();
  return s.length > n ? s.slice(0, Math.max(0, n - 3)) + '...' : s;
}

function esc(s) {
  return String(s == null ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

// Defang URLs / domains so an alert email never contains a live malicious link.
function defang(s) {
  return String(s == null ? '' : s).replace(/^http/i, 'hxxp').replace(/\./g, '[.]');
}

// Same idea for free text (log fields, LLM output): no channel may turn it into a clickable link.
function defangText(s) {
  return String(s == null ? '' : s)
    .replace(/\bhttp(s?):\/\//gi, 'hxxp$1://').replace(/\bftp(s?):\/\//gi, 'fxp$1://').replace(/\bwww\./gi, 'www[.]');
}

// Log-derived text for display: cleaned, defanged and length-capped.
function plain(s, n) {
  return clip(defangText(val(s)), n);
}

function isIPv4(s) {
  return /^(?:(?:25[0-5]|2[0-4]\d|1?\d?\d)\.){3}(?:25[0-5]|2[0-4]\d|1?\d?\d)$/.test(String(s || ''));
}

function isPublicIPv4(s) {
  if (!isIPv4(s)) return false;
  const p = String(s).split('.').map(Number);
  const a = p[0], b = p[1];
  if (a === 0 || a === 10 || a === 127) return false;
  if (a === 100 && b >= 64 && b <= 127) return false;   // CGNAT
  if (a === 169 && b === 254) return false;              // link-local
  if (a === 172 && b >= 16 && b <= 31) return false;
  if (a === 192 && b === 168) return false;
  if (a >= 224) return false;                            // multicast / reserved
  return true;
}

function errText(e) {
  if (!e) return '';
  if (typeof e === 'string') return e;
  const m = e.message || e.description;
  if (typeof m === 'string') return m;
  try { return JSON.stringify(m || e).slice(0, 300); } catch (x) { return 'error'; }
}

// LogRhythm timestamps are UTC with no offset ("2026-10-20T06:32:11.440").
function parseUtc(s) {
  s = String(s || '').trim();
  if (!s) return null;
  const hasTz = /(?:Z|[+-]\d{2}:?\d{2})$/.test(s);
  const d = new Date(hasTz ? s : s + 'Z');
  return isNaN(d.getTime()) ? null : d;
}

function fmtDate(d, tz, label) {
  if (!d) return '';
  return d.toLocaleString('en-GB', {
    timeZone: tz, day: '2-digit', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit'
  }) + ' ' + label;
}

// ===== Validate + Dedupe =====
// Normalises the webhook payload and drops repeat fires of the same alarm.
// LogRhythm Smart Response sometimes fires twice for one alarm within seconds, so an alarm id seen
// again inside a short window is flagged as a duplicate. Test runs ({"demo": true}, optional
// "label": "TEST") neither check nor record anything, so a test can never hide a real alarm.
// Workflow static data is only persisted on production executions, so editor runs never dedupe either.
const DEDUPE_WINDOW_MS = 2 * 60 * 1000;
// true: a test run ({"demo": true}) is tagged [LABEL] in subjects and chat headers so nobody mistakes it for a real alert.
// false: a test run still skips the duplicate check, but nothing is tagged.
const TAG_TEST_RUNS = true;

const item = $input.first().json || {};
const body = item.body || item;

const rawId = body.alarmId ?? body.AlarmId ?? body.alarm_id ?? body.id;
const alarmId = Number(rawId);
if (!Number.isSafeInteger(alarmId) || alarmId <= 0) {
  throw new Error('Invalid webhook payload: alarmId missing or not a positive integer (got ' + clip(JSON.stringify(rawId), 60) + ')');
}

const demo = body.demo === true || body.demo === 'true';
const label = (demo && TAG_TEST_RUNS) ? (clip(body.label || 'DEMO', 12).toUpperCase().replace(/[^A-Z0-9 _-]/g, '') || 'DEMO') : '';

const now = Date.now();
let isDuplicate = false;
if (!demo) {
  const sd = $getWorkflowStaticData('global');
  if (!sd.seen) sd.seen = {};
  Object.keys(sd.seen).forEach((k) => {
    if (now - sd.seen[k] > DEDUPE_WINDOW_MS) delete sd.seen[k];
  });
  isDuplicate = sd.seen[alarmId] !== undefined;
  if (!isDuplicate) sd.seen[alarmId] = now;
}

return [{ json: { alarmId, demo, label, isDuplicate, receivedAt: new Date(now).toISOString() } }];

// ===== shared helpers (prepended to every Code node by make_pipeline.py) =====
// Nothing to configure in this block - settings live at the top of the node that uses them
// (time zone: Extract IOCs + Filter; links, clients, thresholds, model: Risk + MITRE Engine).

const LEVEL_STYLE = {
  critical: { label: 'CRITICAL',     color: '#dc2626', bg: '#fef2f2', border: '#fecaca', emoji: ':red_circle:' },
  high:     { label: 'HIGH',         color: '#ea580c', bg: '#fff7ed', border: '#fed7aa', emoji: ':large_orange_circle:' },
  medium:   { label: 'MEDIUM',       color: '#d97706', bg: '#fffbeb', border: '#fde68a', emoji: ':large_yellow_circle:' },
  low:      { label: 'LOW',          color: '#16a34a', bg: '#f0fdf4', border: '#bbf7d0', emoji: ':large_green_circle:' }
};

