  if (typeof m === 'string') return m;
  try { return JSON.stringify(m || e).slice(0, 300); } catch (x) { return 'error'; }
}

// LogRhythm timestamps are UTC with no offset ("2026-10-20T06:32:11.440").
function parseUtc(s) {
  s = String(s || '').trim();
  if (!s) return null;
  const hasTz = /(?:Z|[+-]\d{2}:?\d{2})$/.test(s);
  const d = new Date(hasTz ? s : s + 'Z');
  return isNaN(d.getTime()) ? null : d;
}

function fmtDate(d, tz, label) {
  if (!d) return '';
  return d.toLocaleString('en-GB', {
    timeZone: tz, day: '2-digit', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit'
  }) + ' ' + label;
}

// ===== Build HTML Email =====
// Outlook-safe table layout, inline styles only. Every dynamic value is HTML-escaped,
// and URLs / domains are defanged so the mail never carries a live malicious link.
const b = $input.first().json;
const alarm = b.alarm, facts = b.facts, ioc = b.ioc, intel = b.intel, risk = b.risk, analyst = b.analyst;
const S = LEVEL_STYLE[risk.level] || LEVEL_STYLE.medium;
const demoTag = b.label ? '[' + b.label + '] ' : '';
const TARGET_TEXT = { internal: 'An internal host', perimeter: 'The perimeter device itself (firewall / VPN gateway)', unknown: '' };

const endpoint = (host, ip, port) => {
  const left = [host, ip ? (host ? '(' + ip + ')' : ip) : ''].filter(Boolean).join(' ');
  return left ? left + (port ? ':' + port : '') : '';
};

function row(label, value, alt) {
  return '<tr style="background:' + (alt ? '#f8fafc' : '#ffffff') + ';">' +
    '<td style="padding:8px 12px; font-weight:bold; width:32%; border:1px solid #e5e7eb; font-size:13px;">' + esc(label) + '</td>' +
    '<td style="padding:8px 12px; border:1px solid #e5e7eb; font-size:13px; word-break:break-all;">' + value + '</td></tr>';
}

// ---- detected activity (rows appear only when the data exists) ----
const d = [];
d.push(['Client', esc(alarm.entity)]);
d.push(['Alarm ID', esc(alarm.id)]);
d.push(['Detected', esc(alarm.dateStr)]);
d.push(['Category', esc(b.category.replace('_', ' ') + (b.direction ? ' / ' + b.direction : ''))]);
const src = endpoint(facts.srcHost, facts.srcIp, facts.srcPort);
const dst = endpoint(facts.host, facts.dstIp, facts.dstPort);
if (src) d.push(['Source', esc(src)]);
if (intel.tor && intel.tor.length) d.push(['Tor exit node', '<b style="color:#dc2626;">Yes</b> (confirmed by ' + esc(intel.tor.join(', ')) + ')']);
if (dst) d.push(['Destination', esc(dst + (facts.natIp ? ' (NAT to ' + facts.natIp + ')' : ''))]);
if (TARGET_TEXT[facts.targetKind]) d.push(['What was hit', esc(TARGET_TEXT[facts.targetKind])]);
if (facts.protocol || facts.service) d.push(['Protocol / Service', esc([facts.protocol, facts.service].filter(Boolean).join(' / '))]);
if (facts.policy) d.push(['Firewall policy', esc(facts.policy)]);
if (facts.user) d.push(['User', esc(facts.user)]);
if (facts.process) d.push(['Process', esc(facts.process)]);
if (facts.product) d.push(['Log source', esc(facts.product)]);
d.push(['Outcome', '<b style="color:' + (facts.outcome === 'allowed' ? '#dc2626' : facts.outcome === 'blocked' ? '#16a34a' : '#64748b') + ';">' + esc(facts.outcome) + '</b>']);
d.push(['Events', esc(alarm.eventCount)]);
const detailRows = d.map((r, i) => row(r[0], r[1], i % 2 === 0)).join('');

// ---- threat intel ----
const VC = { malicious: '#dc2626', suspicious: '#ea580c', clean: '#16a34a', 'not seen': '#64748b', unavailable: '#94a3b8' };
let intelHtml;
if (intel.rows.length) {
  intelHtml = '<table width="100%" style="border-collapse:collapse; font-size:13px;">' +
    '<tr style="background:#f1f5f9;"><td style="padding:6px 10px; border:1px solid #e5e7eb; font-weight:bold;">Source</td>' +
    '<td style="padding:6px 10px; border:1px solid #e5e7eb; font-weight:bold;">Verdict</td>' +
    '<td style="padding:6px 10px; border:1px solid #e5e7eb; font-weight:bold;">Detail</td></tr>' +
    intel.rows.map((r) =>
      '<tr><td style="padding:6px 10px; border:1px solid #e5e7eb;">' + (r.link ? '<a href="' + esc(r.link) + '" style="color:#2563eb; text-decoration:none;">' + esc(r.source) + '</a>' : esc(r.source)) + '</td>' +
      '<td style="padding:6px 10px; border:1px solid #e5e7eb; font-weight:bold; color:' + (VC[r.verdict] || '#64748b') + ';">' + esc(r.verdict.toUpperCase()) + '</td>' +
      '<td style="padding:6px 10px; border:1px solid #e5e7eb;">' + esc(r.text) + '</td></tr>').join('') +
    '</table>';
} else {
  intelHtml = '<p style="margin:0; font-size:13px; color:#64748b;">No external lookups were run: no public remote IP was found in the logs (' +
    esc(ioc.filteredCount) + ' internal / benign address(es) filtered).</p>';
}

// ---- other sections ----
const mitreHtml = b.mitre.length
  ? b.mitre.map((m) => '<span style="display:inline-block; background:#eef2ff; color:#3730a3; border:1px solid #c7d2fe; border-radius:4px; padding:3px 8px; margin:2px 4px 2px 0; font-size:12px;">' +
      esc(m.id) + ' ' + esc(m.name) + '</span>').join('')
  : '<span style="font-size:13px; color:#64748b;">No technique mapped for this alarm type.</span>';

const reasonsHtml = '<ul style="margin:0; padding-left:18px; font-size:12px; line-height:1.6; color:#475569;">' +
  risk.reasons.map((r) => '<li>' + esc(r) + '</li>').join('') + '</ul>';

const actionsHtml = '<ol style="margin:0; padding-left:20px; font-size:14px; line-height:1.7;">' +
  analyst.actions.map((a) => '<li>' + esc(a) + '</li>').join('') + '</ol>';

const aiLabel = analyst.source === 'llm' ? 'AI Analyst Assessment (' + esc(analyst.model || 'local LLM') + ', confidence: ' + esc(analyst.confidence) + ')'
  : analyst.source === 'llm-unstructured' ? 'AI Analyst Assessment (unstructured reply)'
  : 'Automatic Assessment (AI unavailable)';

const barOn = Math.max(1, Math.min(100, risk.score));
const bar = '<table width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;"><tr>' +
  '<td width="' + barOn + '%" height="10" bgcolor="' + S.color + '" style="font-size:1px; line-height:1px;">&nbsp;</td>' +
  (barOn < 100 ? '<td width="' + (100 - barOn) + '%" height="10" bgcolor="#e5e7eb" style="font-size:1px; line-height:1px;">&nbsp;</td>' : '') +
