'<td width="33%"></td></tr></table></td></tr>' +

'<tr><td style="padding:20px 25px; border-bottom:1px solid #e5e7eb;"><table width="100%"><tr><td>' +
'<p style="margin:0 0 4px 0; font-size:11px; font-weight:bold; color:#64748b; letter-spacing:0.05em;">' + esc(demoTag + b.category.replace('_', ' ').toUpperCase()) + '</p>' +
'<h2 style="margin:0; color:' + S.color + ';">' + esc(alarm.ruleShort) + '</h2></td>' +
'<td align="right" valign="top"><span style="background:' + S.color + '; color:#ffffff; padding:6px 12px; border-radius:6px; font-size:12px; font-weight:bold;">' + esc(S.label) + '</span></td>' +
'</tr></table></td></tr>' +

'<tr><td style="padding:20px 25px 5px 25px;"><table width="100%" style="background:' + S.bg + '; border:1px solid ' + S.border + '; border-radius:8px;"><tr><td style="padding:14px 16px;">' +
'<p style="margin:0 0 6px 0; font-size:13px;"><b>Risk score: <span style="color:' + S.color + ';">' + esc(risk.score) + ' / 100</span></b> &nbsp;|&nbsp; Intel coverage: ' + esc(risk.intelCoverage) + '</p>' +
bar + '</td></tr></table></td></tr>' +

'<tr><td style="padding:15px 25px 5px 25px;"><h3 style="margin:0 0 8px 0; font-size:16px; color:#111827;">' + aiLabel + '</h3>' +
'<p style="margin:0 0 8px 0; font-size:14px; line-height:1.6;">' + esc(analyst.summary) + '</p>' +
(analyst.assessment ? '<p style="margin:0 0 6px 0; font-size:14px; line-height:1.6;"><b>Assessment:</b> ' + esc(analyst.assessment) + '</p>' : '') +
'<p style="margin:0; font-size:11px; color:#94a3b8;">Generated text is advisory. Routing and severity come from the deterministic risk engine below.</p></td></tr>' +

'<tr><td style="padding:15px 25px 5px 25px;"><h3 style="margin:0 0 8px 0; font-size:16px; color:#111827;">Detected Activity</h3>' +
'<table width="100%" style="border-collapse:collapse;">' + detailRows + '</table></td></tr>' +

