'<tr><td style="padding:20px 25px 30px 25px; text-align:center;"><a href="' + esc(consoleUrl) + '" target="_blank" ' +
'style="background-color:' + S.color + '; color:#ffffff; padding:12px 24px; text-decoration:none; border-radius:6px; font-weight:bold; font-size:14px; display:inline-block; font-family:Arial, sans-serif;">View Alert in Web Console</a></td></tr>' +

