'</table></td></tr></table></body></html>';

const emailSubject = clip(demoTag + 'Alarm ID: ' + alarm.id + ' - ' + alarm.entity + ': ' + alarm.ruleShort + ' [' + S.label + ']', 250);   // one line, no CR/LF

return [{ json: Object.assign({}, b, { emailSubject, emailHtml }) }];

// ===== shared helpers (prepended to every Code node by make_pipeline.py) =====
// Nothing to configure in this block - settings live at the top of the node that uses them
// (time zone: Extract IOCs + Filter; links, clients, thresholds, model: Risk + MITRE Engine).

const LEVEL_STYLE = {
  critical: { label: 'CRITICAL',     color: '#dc2626', bg: '#fef2f2', border: '#fecaca', emoji: ':red_circle:' },
  high:     { label: 'HIGH',         color: '#ea580c', bg: '#fff7ed', border: '#fed7aa', emoji: ':large_orange_circle:' },
  medium:   { label: 'MEDIUM',       color: '#d97706', bg: '#fffbeb', border: '#fde68a', emoji: ':large_yellow_circle:' },
  low:      { label: 'LOW',          color: '#16a34a', bg: '#f0fdf4', border: '#bbf7d0', emoji: ':large_green_circle:' }
};

// Invisible / bidirectional-override characters can disguise text in an alert (U+202E reverses what follows);
// control characters would break subjects and table rows. Both are stripped from everything read from the logs.
const INVISIBLE_RE = /[\u200b-\u200f\u202a-\u202e\u2066-\u2069\ufeff]/g;
const CONTROL_RE = /[\u0000-\u001f\u007f]+/g;

function val(s) {
  if (s === undefined || s === null) return '';
  s = String(s).replace(INVISIBLE_RE, '').replace(CONTROL_RE, ' ').trim();
  const l = s.toLowerCase();
  if (s === '' || s === '-' || l === 'null' || l === '(null)' || l === 'n/a' || l === 'none' || l === 'undefined') return '';
  return s;
}

function clip(s, n) {
  s = String(s == null ? '' : s).replace(INVISIBLE_RE, '').replace(CONTROL_RE, ' ').replace(/\s+/g, ' ').trim();
  return s.length > n ? s.slice(0, Math.max(0, n - 3)) + '...' : s;
}

function esc(s) {
  return String(s == null ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

// Defang URLs / domains so an alert email never contains a live malicious link.
function defang(s) {
  return String(s == null ? '' : s).replace(/^http/i, 'hxxp').replace(/\./g, '[.]');
}

// Same idea for free text (log fields, LLM output): no channel may turn it into a clickable link.
function defangText(s) {
  return String(s == null ? '' : s)
    .replace(/\bhttp(s?):\/\//gi, 'hxxp$1://').replace(/\bftp(s?):\/\//gi, 'fxp$1://').replace(/\bwww\./gi, 'www[.]');
}

// Log-derived text for display: cleaned, defanged and length-capped.
function plain(s, n) {
  return clip(defangText(val(s)), n);
}

function isIPv4(s) {
  return /^(?:(?:25[0-5]|2[0-4]\d|1?\d?\d)\.){3}(?:25[0-5]|2[0-4]\d|1?\d?\d)$/.test(String(s || ''));
}

function isPublicIPv4(s) {
  if (!isIPv4(s)) return false;
  const p = String(s).split('.').map(Number);
  const a = p[0], b = p[1];
  if (a === 0 || a === 10 || a === 127) return false;
  if (a === 100 && b >= 64 && b <= 127) return false;   // CGNAT
  if (a === 169 && b === 254) return false;              // link-local
  if (a === 172 && b >= 16 && b <= 31) return false;
  if (a === 192 && b === 168) return false;
  if (a >= 224) return false;                            // multicast / reserved
  return true;
}

function errText(e) {
  if (!e) return '';
  if (typeof e === 'string') return e;
  const m = e.message || e.description;
  if (typeof m === 'string') return m;
  try { return JSON.stringify(m || e).slice(0, 300); } catch (x) { return 'error'; }
}

// LogRhythm timestamps are UTC with no offset ("2026-10-20T06:32:11.440").
function parseUtc(s) {
  s = String(s || '').trim();
  if (!s) return null;
  const hasTz = /(?:Z|[+-]\d{2}:?\d{2})$/.test(s);
  const d = new Date(hasTz ? s : s + 'Z');
  return isNaN(d.getTime()) ? null : d;
}

function fmtDate(d, tz, label) {
  if (!d) return '';
  return d.toLocaleString('en-GB', {
    timeZone: tz, day: '2-digit', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit'
  }) + ' ' + label;
}

// ===== Build Slack + MM Payloads =====
// Slack Block Kit (as a JSON string for the Slack node), a Mattermost markdown post, and the
// comment that gets written back to the LogRhythm alarm. All free text is neutralised so
// log content or LLM output cannot inject mentions, links or table breaks.
const b = $input.first().json;
const MM_USERNAME = 'soc-pipeline';        // display name on the Mattermost post
const alarm = b.alarm, facts = b.facts, intel = b.intel, risk = b.risk, analyst = b.analyst;
const S = LEVEL_STYLE[risk.level] || LEVEL_STYLE.medium;
const demoTag = b.label ? '[' + b.label + '] ' : '';
const consoleUrl = b.links.console;
const TARGET_TEXT = { internal: 'internal host', perimeter: 'perimeter device only', unknown: '' };

const sx = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');          // Slack mrkdwn escaping
const mm = (s) => String(s == null ? '' : s).replace(/[\r\n]+/g, ' ').replace(/\|/g, '/').replace(/`/g, "'").replace(/@/g, '@\u200b').replace(/\]\(/g, ']\u200b(');  // Mattermost: no mentions, no table / code / link breaks
// clip() flattens line breaks (right for subjects, wrong for Slack sections made of several lines), so keep them here
const clipMl = (s, n) => {
  s = String(s == null ? '' : s).replace(INVISIBLE_RE, '').replace(/\r/g, '').replace(/[\u0000-\u0009\u000b-\u001f\u007f]+/g, ' ')
    .replace(/[ \t]+/g, ' ').replace(/ ?\n ?/g, '\n').trim();
  return s.length > n ? s.slice(0, Math.max(0, n - 3)) + '...' : s;
};

const src = [facts.srcHost, facts.srcIp ? (facts.srcHost ? '(' + facts.srcIp + ')' : facts.srcIp) : ''].filter(Boolean).join(' ') + (facts.srcPort ? ':' + facts.srcPort : '');
const dst = [facts.host, facts.dstIp ? (facts.host ? '(' + facts.dstIp + ')' : facts.dstIp) : ''].filter(Boolean).join(' ') + (facts.dstPort ? ':' + facts.dstPort : '');
const mitreIds = b.mitre.map((m) => m.id).join(', ');
const intelLine = (intel.rows.length
  ? intel.rows.map((r) => r.source + ': ' + r.verdict).join(' | ')
  : 'no public remote IP to enrich') + (intel.tor && intel.tor.length ? ' | Tor exit node (' + intel.tor.join(', ') + ')' : '');

// ---------------- Slack ----------------
const fields = [
  '*Client*\n' + sx(alarm.entity),
  '*Alarm ID*\n`' + alarm.id + '`',
  '*Risk score*\n' + risk.score + ' / 100',
  '*Outcome*\n' + sx(facts.outcome)
];
if (src) fields.push('*Source*\n' + sx(src));
if (dst) fields.push('*Destination*\n' + sx(dst));
if (TARGET_TEXT[facts.targetKind]) fields.push('*What was hit*\n' + TARGET_TEXT[facts.targetKind]);
if (facts.user) fields.push('*User*\n' + sx(facts.user));

const blocks = [
  { type: 'header', text: { type: 'plain_text', text: clip(demoTag + S.label + ' - ' + alarm.entity + ': ' + alarm.ruleShort, 145), emoji: true } },
  { type: 'section', fields: fields.slice(0, 10).map((t) => ({ type: 'mrkdwn', text: clipMl(t, 1900) })) },
  { type: 'section', text: { type: 'mrkdwn', text: clipMl('*AI analyst*  _(' + (analyst.source === 'llm' ? 'confidence: ' + analyst.confidence : 'AI unavailable') + ')_\n' + sx(analyst.summary), 2900) } },
  { type: 'section', text: { type: 'mrkdwn', text: clipMl('*Threat intel*\n' + sx(intelLine), 2900) } },
  { type: 'section', text: { type: 'mrkdwn', text: clipMl('*Next steps*\n' + analyst.actions.map((a, i) => (i + 1) + '. ' + sx(a)).join('\n'), 2900) } },
  { type: 'context', elements: [{ type: 'mrkdwn', text: clipMl('MITRE: ' + (mitreIds || 'n/a') + '  |  ' + sx(alarm.dateStr), 1900) }] },
  { type: 'actions', elements: [{ type: 'button', text: { type: 'plain_text', text: 'Open in Web Console' }, url: consoleUrl, style: (risk.level === 'critical' || risk.level === 'high') ? 'danger' : 'primary' }] }
];
const slackBlocks = JSON.stringify({ blocks });
const slackText = sx(clip(demoTag + S.label + ' - ' + alarm.entity + ': ' + alarm.ruleShort + ' (alarm ' + alarm.id + ', score ' + risk.score + ')', 300));

// ---------------- Mattermost ----------------
const rows = [
  '| :office: **Client** | ' + mm(alarm.entity) + ' |',
  '| :id: **Alarm ID** | `' + alarm.id + '` |',
  '| :bar_chart: **Risk score** | **' + risk.score + ' / 100** (' + S.label + ') |',
  src ? '| :globe_with_meridians: **Source** | `' + mm(src) + '` |' : null,
  dst ? '| :computer: **Destination** | `' + mm(dst) + '` |' : null,
  facts.user ? '| :bust_in_silhouette: **User** | `' + mm(facts.user) + '` |' : null,
  TARGET_TEXT[facts.targetKind] ? '| :dart: **What was hit** | ' + TARGET_TEXT[facts.targetKind] + ' |' : null,
  '| :shield: **Outcome** | ' + mm(facts.outcome) + ' |',
  '| :mag: **Threat intel** | ' + mm(intelLine) + ' |',
  mitreIds ? '| :crossed_swords: **MITRE** | ' + mm(mitreIds) + ' |' : null,
  '| :robot_face: **AI summary** | ' + mm(clip(analyst.summary, 450)) + ' |',
  '| :clock1: **Detected** | ' + mm(alarm.dateStr) + ' |'
].filter(Boolean).join('\n');

const mmText = ':rotating_light: **INBOUND ALARM TRIAGE - ' + mm(demoTag) + S.label + ' ALERT** :rotating_light:\n\n' +
  '**Rule:** ' + mm(alarm.ruleShort) + '\n\n---\n\n| Field | Details |\n|:---|:---|\n' + rows +
  '\n\n**Next steps**\n' + analyst.actions.map((a, i) => (i + 1) + '. ' + mm(a)).join('\n') +
  '\n\n[:link: Open in Web Console](' + consoleUrl + ')\n\n---\n:shield: *Automated Triage Pipeline*';
const mmPayload = { text: mmText.slice(0, 15000), username: MM_USERNAME };

// ---------------- LogRhythm comment ----------------
const lrComment = clip('[Triage pipeline' + (b.label ? ' ' + b.label : '') + '] Triage: ' + S.label + ', score ' + risk.score + '/100. Outcome: ' + facts.outcome +
  '. Intel: ' + intelLine + '. Summary: ' + analyst.summary, 900);

return [{ json: Object.assign({}, b, { slackBlocks, slackText, mmPayload, lrComment }) }];
